vm.runInContext(source+'\\nglobalThis.hooks={state,visibleMail,openMail,performArchive,performTrash,undoLastAction,beginCompose,sendMail,setFolder,searchMatch,snooze};',context);
const h=context.hooks;
assert.equal(h.state.mail.length,28,'seeded conversations');
h.state.query='from:maya';assert.equal(h.visibleMail().length,1,'from operator');assert.equal(h.visibleMail()[0].id,'m1');
